window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6a55aeffd3c65718"]={"versions": [{"id": "FIG-6a55aeffd3c65718", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Datenflussdiagramm nach der AUTOSAR-Methodik-Notation zur Darstellung der Phasen, Aktivitäten und Artefakte im Prozess der ECU-Konfiguration innerhalb der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Aktivitätsschritte (abgerundete Rechtecke mit Werkzeug-/Dokument-Symbolen):</p>\n<ul class=\"fig-list\">\n<li><code>Prepare ECU Configuration</code></li>\n<li><code>Configure BSW and RTE</code></li>\n<li><code>Generate BSW and RTE</code></li>\n</ul>\n<p class=\"fig-p\">Sowie fünf Typen von Ein- und Ausgangsartefakten bzw. Dokumenten:</p>\n<ul class=\"fig-list\">\n<li><code>ECU Extract</code>: Eingangsdokument (Briefumschlag-Symbol mit Perforationslinie links), Multiplizität 1.</li>\n<li><code>BSW Module Delivered Bundle</code>: Eingangsdokument (Briefumschlag-Symbol mit Perforationslinie links), Multiplizität 1..*.</li>\n<li><code>ECU Configuration Values</code>: Zentrales Konfigurationsdokument (Dokumentensymbol), Multiplizität jeweils 1.</li>\n<li><code>BSW Module Configuration Data Source Code</code>: Generiertes Quellcode-Artefakt (.c), Multiplizität 1.</li>\n<li><code>BSW Module Configuration Header File</code>: Generierte Header-Datei (.h), Multiplizität 1.</li>\n<li><code>RTE Source</code>: Generierter RTE-Quellcode/Header, Multiplizität 1.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellenbeziehungen:</p>\n<ul class=\"fig-list\">\n<li>Gerichtet von <code>ECU Extract</code> (Kardinalität 1) zu <code>Prepare ECU Configuration</code> mit Stereotyp <code>«input»</code>.</li>\n<li>Gerichtet von <code>BSW Module Delivered Bundle</code> (Kardinalität 1..*) zu <code>Prepare ECU Configuration</code> mit Stereotyp <code>«input»</code>.</li>\n<li>Gerichtet von <code>Prepare ECU Configuration</code> zu <code>ECU Configuration Values</code> (Kardinalität 1) mit Stereotyp <code>«output»</code>.</li>\n<li>Bidirektional zwischen <code>Configure BSW and RTE</code> und <code>ECU Configuration Values</code> (Kardinalität 1) mit Stereotyp <code>«inoutput»</code>.</li>\n<li>Gerichtet von <code>ECU Configuration Values</code> (Kardinalität 1) zu <code>Generate BSW and RTE</code> mit Stereotyp <code>«input»</code>.</li>\n<li>Gerichtet von <code>Generate BSW and RTE</code> zu <code>BSW Module Configuration Data Source Code</code> (Kardinalität 1) mit Stereotyp <code>«output»</code>.</li>\n<li>Gerichtet von <code>Generate BSW and RTE</code> zu <code>BSW Module Configuration Header File</code> (Kardinalität 1) mit Stereotyp <code>«output»</code>.</li>\n<li>Gerichtet von <code>Generate BSW and RTE</code> zu <code>RTE Source</code> (Kardinalität 1) mit Stereotyp <code>«output»</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Prozess gliedert sich in drei aufeinander aufbauende Sequenzschritte:</p>\n<ol class=\"fig-list\">\n<li>Vorbereitung (<code>Prepare ECU Configuration</code>): Zusammenführung des <code>ECU Extract</code> (aus der Systembeschreibung extrahierte systemspezifische ECU-Daten) mit den Beschreibungen aus mindestens einem <code>BSW Module Delivered Bundle</code> zur initialen Erzeugung der <code>ECU Configuration Values</code>.</li>\n<li>Iterative Konfiguration (<code>Configure BSW and RTE</code>): Lesen und Rückschreiben (<code>«inoutput»</code>) der <code>ECU Configuration Values</code> im Konfigurationseditor zur Vervollständigung und Anpassung aller BSW- und RTE-Parameter.</li>\n<li>Code- und Header-Generierung (<code>Generate BSW and RTE</code>): Verarbeiten der finalen <code>ECU Configuration Values</code> durch die Generatoren zur Erzeugung der kompilierbaren Artefakte <code>BSW Module Configuration Data Source Code</code>, <code>BSW Module Configuration Header File</code> und <code>RTE Source</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Übersichtsschaubild des AUTOSAR-Methodik-Workflows für die ECU-Konfiguration. Es definiert die verbindlichen Eingangsartefakte für die Konfigurationswerkzeuge (mindestens ein BSW-Paket erforderlich, dargestellt durch Kardinalität <code>1..*</code>) sowie die Trennung zwischen Konfigurationswerten (ARXML) und generiertem C-Code bzw. Header-Dateien. Werkzeugketten müssen sicherstellen, dass Konfigurationseditoren den Roundtrip (<code>«inoutput»</code>) auf den Konfigurationswerten unterstützen und Generatoren ausschließlich auf den konsolidierten Konfigurationswerten aufsetzen.</p>"}, {"id": "FIG-704f08b10edd1e18", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Datenflussdiagramm nach der AUTOSAR-Methodik-Notation zur Darstellung der Phasen, Aktivitäten und Artefakte im Prozess der ECU-Konfiguration innerhalb der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Aktivitätsschritte (abgerundete Rechtecke mit Werkzeug-/Dokument-Symbolen):</p>\n<ul class=\"fig-list\">\n<li><code>Prepare ECU Configuration</code></li>\n<li><code>Configure BSW and RTE</code></li>\n<li><code>Generate BSW and RTE</code></li>\n</ul>\n<p class=\"fig-p\">Sowie fünf Typen von Ein- und Ausgangsartefakten bzw. Dokumenten:</p>\n<ul class=\"fig-list\">\n<li><code>ECU Extract</code>: Eingangsdokument (Briefumschlag-Symbol mit Perforationslinie links).</li>\n<li><code>BSW Module Delivered Bundle</code>: Eingangsdokument (Briefumschlag-Symbol mit Perforationslinie links), Multiplizität 1..*.</li>\n<li><code>ECU Configuration Values</code>: Zentrales Konfigurationsdokument (Dokumentensymbol), Multiplizität jeweils 1.</li>\n<li><code>BSW Module Configuration Data Source Code</code>: Generiertes Quellcode-Artefakt (.c), Multiplizität 1.</li>\n<li><code>BSW Module Configuration Header File</code>: Generierte Header-Datei (.h), Multiplizität 1.</li>\n<li><code>RTE Source</code>: Generierter RTE-Quellcode/Header, Multiplizität 1.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellenbeziehungen:</p>\n<ul class=\"fig-list\">\n<li>Gerichtet von <code>ECU Extract</code> zu <code>Prepare ECU Configuration</code> mit Stereotyp <code>«input»</code>.</li>\n<li>Gerichtet von <code>BSW Module Delivered Bundle</code> (Kardinalität 1..*) zu <code>Prepare ECU Configuration</code> mit Stereotyp <code>«input»</code>.</li>\n<li>Gerichtet von <code>Prepare ECU Configuration</code> zu <code>ECU Configuration Values</code> (Kardinalität 1) mit Stereotyp <code>«output»</code>.</li>\n<li>Bidirektional zwischen <code>Configure BSW and RTE</code> und <code>ECU Configuration Values</code> (Kardinalität 1) mit Stereotyp <code>«inoutput»</code>.</li>\n<li>Gerichtet von <code>ECU Configuration Values</code> (Kardinalität 1) zu <code>Generate BSW and RTE</code> mit Stereotyp <code>«input»</code>.</li>\n<li>Gerichtet von <code>Generate BSW and RTE</code> zu <code>BSW Module Configuration Data Source Code</code> (Kardinalität 1) mit Stereotyp <code>«output»</code>.</li>\n<li>Gerichtet von <code>Generate BSW and RTE</code> zu <code>BSW Module Configuration Header File</code> (Kardinalität 1) mit Stereotyp <code>«output»</code>.</li>\n<li>Gerichtet von <code>Generate BSW and RTE</code> zu <code>RTE Source</code> (Kardinalität 1) mit Stereotyp <code>«output»</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Prozess gliedert sich in drei aufeinander aufbauende Sequenzschritte:</p>\n<ol class=\"fig-list\">\n<li>Vorbereitung (<code>Prepare ECU Configuration</code>): Zusammenführung des <code>ECU Extract</code> (aus der Systembeschreibung extrahierte systemspezifische ECU-Daten) mit den Beschreibungen aus mindestens einem <code>BSW Module Delivered Bundle</code> zur initialen Erzeugung der <code>ECU Configuration Values</code>.</li>\n<li>Iterative Konfiguration (<code>Configure BSW and RTE</code>): Lesen und Rückschreiben (<code>«inoutput»</code>) der <code>ECU Configuration Values</code> im Konfigurationseditor zur Vervollständigung und Anpassung aller BSW- und RTE-Parameter.</li>\n<li>Code- und Header-Generierung (<code>Generate BSW and RTE</code>): Verarbeiten der finalen <code>ECU Configuration Values</code> durch die Generatoren zur Erzeugung der kompilierbaren Artefakte <code>BSW Module Configuration Data Source Code</code>, <code>BSW Module Configuration Header File</code> und <code>RTE Source</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Übersichtsschaubild des AUTOSAR-Methodik-Workflows für die ECU-Konfiguration. Es definiert die verbindlichen Eingangsartefakte für die Konfigurationswerkzeuge (mindestens ein BSW-Paket erforderlich, dargestellt durch Kardinalität <code>1..*</code>) sowie die Trennung zwischen Konfigurationswerten (ARXML) und generiertem C-Code bzw. Header-Dateien. Werkzeugketten müssen sicherstellen, dass Konfigurationseditoren den Roundtrip (<code>«inoutput»</code>) auf den Konfigurationswerten unterstützen und Generatoren ausschließlich auf den konsolidierten Konfigurationswerten aufsetzen.</p>"}, {"id": "FIG-eaae0519230b5591", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Datenflussdiagramm nach der AUTOSAR-Methodik-Notation zur Darstellung der Phasen, Aktivitäten und Artefakte im Prozess der ECU-Konfiguration innerhalb der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Aktivitätsschritte (abgerundete Rechtecke mit Werkzeug-/Dokument-Symbolen):</p>\n<ul class=\"fig-list\">\n<li><code>Prepare ECU Configuration</code></li>\n<li><code>Configure BSW and RTE</code></li>\n<li><code>Generate BSW and RTE</code></li>\n</ul>\n<p class=\"fig-p\">Sowie fünf Typen von Ein- und Ausgangsartefakten bzw. Dokumenten:</p>\n<ul class=\"fig-list\">\n<li><code>ECU Extract</code>: Eingangsdokument (Briefumschlag-Symbol mit Perforationslinie links).</li>\n<li><code>BSW Module Delivered Bundle</code>: Eingangsdokument (Briefumschlag-Symbol mit Perforationslinie links), Multiplizität 1..*.</li>\n<li><code>ECU Configuration Values</code>: Zentrales Konfigurationsdokument (Dokumentensymbol), Multiplizität jeweils 1.</li>\n<li><code>BSW Module Configuration Data Source Code</code>: Generiertes Quellcode-Artefakt (.c), Multiplizität 1.</li>\n<li><code>BSW Module Configuration Header File</code>: Generierte Header-Datei (.h), Multiplizität 1.</li>\n<li><code>RTE Source</code>: Generierter RTE-Quellcode/Header, Multiplizität 1.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellenbeziehungen:</p>\n<ul class=\"fig-list\">\n<li>Gerichtet von <code>ECU Extract</code> zu <code>Prepare ECU Configuration</code> mit Stereotyp <code>«input»</code>.</li>\n<li>Gerichtet von <code>BSW Module Delivered Bundle</code> (Kardinalität 1..*) zu <code>Prepare ECU Configuration</code> mit Stereotyp <code>«input»</code>.</li>\n<li>Gerichtet von <code>Prepare ECU Configuration</code> zu <code>ECU Configuration Values</code> (Kardinalität 1) mit Stereotyp <code>«output»</code>.</li>\n<li>Bidirektional zwischen <code>Configure BSW and RTE</code> und <code>ECU Configuration Values</code> (Kardinalität 1) mit Stereotyp <code>«inoutput»</code>.</li>\n<li>Gerichtet von <code>ECU Configuration Values</code> (Kardinalität 1) zu <code>Generate BSW and RTE</code> mit Stereotyp <code>«input»</code>.</li>\n<li>Gerichtet von <code>Generate BSW and RTE</code> zu <code>BSW Module Configuration Data Source Code</code> (Kardinalität 1) mit Stereotyp <code>«output»</code>.</li>\n<li>Gerichtet von <code>Generate BSW and RTE</code> zu <code>BSW Module Configuration Header File</code> (Kardinalität 1) mit Stereotyp <code>«output»</code>.</li>\n<li>Gerichtet von <code>Generate BSW and RTE</code> zu <code>RTE Source</code> (Kardinalität 1) mit Stereotyp <code>«output»</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Prozess gliedert sich in drei aufeinander aufbauende Sequenzschritte:</p>\n<ol class=\"fig-list\">\n<li>Vorbereitung (<code>Prepare ECU Configuration</code>): Zusammenführung des <code>ECU Extract</code> (aus der Systembeschreibung extrahierte systemspezifische ECU-Daten) mit den Beschreibungen aus mindestens einem <code>BSW Module Delivered Bundle</code> zur initialen Erzeugung der <code>ECU Configuration Values</code>.</li>\n<li>Iterative Konfiguration (<code>Configure BSW and RTE</code>): Lesen und Rückschreiben (<code>«inoutput»</code>) der <code>ECU Configuration Values</code> im Konfigurationseditor zur Vervollständigung und Anpassung aller BSW- und RTE-Parameter.</li>\n<li>Code- und Header-Generierung (<code>Generate BSW and RTE</code>): Verarbeiten der finalen <code>ECU Configuration Values</code> durch die Generatoren zur Erzeugung der kompilierbaren Artefakte <code>BSW Module Configuration Data Source Code</code>, <code>BSW Module Configuration Header File</code> und <code>RTE Source</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Übersichtsschaubild des AUTOSAR-Methodik-Workflows für die ECU-Konfiguration. Es definiert die verbindlichen Eingangsartefakte für die Konfigurationswerkzeuge (mindestens ein BSW-Paket erforderlich, dargestellt durch Kardinalität <code>1..*</code>) sowie die Trennung zwischen Konfigurationswerten (ARXML) und generiertem C-Code bzw. Header-Dateien. Werkzeugketten müssen sicherstellen, dass Konfigurationseditoren den Roundtrip (<code>«inoutput»</code>) auf den Konfigurationswerten unterstützen und Generatoren ausschließlich auf den konsolidierten Konfigurationswerten aufsetzen.</p>"}], "trans": [{"from": "FIG-6a55aeffd3c65718", "to": "FIG-704f08b10edd1e18", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Pfeilbeschriftung zwischen <code>ECU Extract</code> und <code>Prepare ECU Configuration</code>: Die Kardinalität <code>1</code> am Pfeilursprung entfällt; die Stereotyp-Beschriftung <code>«input»</code> ist leicht verschoben.</li>\n<li>Pfeilbeschriftung zwischen <code>ECU Configuration Values</code> und <code>Generate BSW and RTE</code>: Das Stereotyp <code>«input»</code> ist von oberhalb des Pfeils nach links direkt auf die Pfeillinie über das Dokument-Symbol verschoben.</li>\n<li>Pfeilbeschriftung zwischen <code>Configure BSW and RTE</code> und <code>ECU Configuration Values</code>: Die vertikal ausgerichtete Beschriftung <code>«inoutput»</code> ist leicht nach links versetzt, sodass die Pfeillinie durch den Buchstaben <code>o</code> verläuft.</li>\n</ul>"}, {"from": "FIG-704f08b10edd1e18", "to": "FIG-eaae0519230b5591", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
